-- File storage metadata. Backs attachments and receipts only; the vault is
-- not a feature here. See docs/data-model.md#files.

CREATE TABLE vault_files (
    id           text PRIMARY KEY,
    workspace_id text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    name         text NOT NULL,
    -- Generated by the API as wsp/{workspace_id}/{file_id}. A client-supplied
    -- filename never becomes a path (SEC-13).
    key          text NOT NULL,
    size         bigint NOT NULL,
    -- Sniffed from the bytes and checked against the declared type (SEC-12).
    type         text NOT NULL CHECK (
                     type IN ('image/jpeg', 'image/png', 'image/webp', 'application/pdf')
                 ),
    sha256       text,
    status       text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'ready')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    deleted_at   timestamptz
);

CREATE INDEX vault_files_workspace_idx
    ON vault_files (workspace_id) WHERE deleted_at IS NULL;

CREATE UNIQUE INDEX vault_files_key_idx ON vault_files (key);
